import {
  PropertiesPanel,
  PropertiesSection,
  PropertiesRow,
} from "@/components/bevelui/properties-panel";
import { IconLayout, IconPalette } from "@tabler/icons-react";

<PropertiesPanel className="w-64">
  <PropertiesSection title="Layout" icon={IconLayout}>
    <PropertiesRow
      label="Width"
      control={{ type: "number", value: 320, unit: "px", onChange: setWidth }}
    />
    <PropertiesRow
      label="Height"
      control={{ type: "number", value: 240, unit: "px", onChange: setHeight }}
    />
    {/* Custom controls slot in alongside typed rows */}
    <PropertiesRow
      label="Blend"
      control={{
        type: "custom",
        render: () => <BlendModeSelect value={blend} onChange={setBlend} />,
      }}
    />
  </PropertiesSection>

  <PropertiesSection title="Fill" icon={IconPalette} defaultOpen={false}>
    <PropertiesRow
      label="Color"
      control={{ type: "color", value: color, onChange: setColor }}
    />
    <PropertiesRow
      label="Opacity"
      control={{ type: "slider", value: opacity, min: 0, max: 100, onChange: setOpacity }}
    />
  </PropertiesSection>
</PropertiesPanel>

